const triggerData = $('When Executed by Another Workflow').first().json;
const catalog = $input.all().map(item => item.json);

let items = triggerData.line_items || [];
if (typeof items === 'string') {
  try { items = JSON.parse(items); } catch (e) { items = []; }
}

let hasMismatch = false;
const auditDetails = [];

for (const item of items) {
  const match = catalog.find(
    c => (item.sku && c.sku.toLowerCase() === String(item.sku).toLowerCase()) ||
         c.item_name.toLowerCase().includes(String(item.item_name || '').toLowerCase().slice(0, 12))
  );

  if (!match) {
    hasMismatch = true;
    auditDetails.push(`⚠️ Нет в прайсе: "${item.item_name}" по цене ${item.unit_price}`);
  } else if (Number(item.unit_price) > Number(match.approved_unit_price)) {
    hasMismatch = true;
    const diff = Number(item.unit_price) - Number(match.approved_unit_price);
    auditDetails.push(`🚨 ЗАВЫШЕНИЕ ЦЕНЫ по "${match.item_name}" (${match.sku}): в счёте ${item.unit_price}, в прайсе ${match.approved_unit_price} (переплата +${diff} за ед.)`);
  } else {
    auditDetails.push(`✅ Цена ОК: "${match.item_name}" (${item.unit_price} <= ${match.approved_unit_price})`);
  }
}

return [{
  json: {
    has_price_mismatch: hasMismatch,
    catalog_report: auditDetails.join('\n') || 'Позиции не переданы'
  }
}];
